mapper.select:
SELECT p.tech_pack_id AS pack_id, v.size_code FROM tp_spec_value v JOIN tp_spec_point p ON p.id = v.spec_point_id
WHERE p.tech_pack_id IN #{id}
UNION
SELECT b.tech_pack_id AS pack_id, s.size_code FROM tp_bom_item_size s JOIN tp_bom_item b ON b.id = s.bom_item_id
WHERE b.tech_pack_id IN #{id}
UNION
SELECT b.tech_pack_id AS pack_id, s.size_code FROM tp_bom_item_sku s JOIN tp_bom_item b ON b.id = s.bom_item_id
WHERE b.tech_pack_id IN #{id}
  AND s.size_code IS NOT NULL
ORDER BY pack_id, size_code

SELECT s.id AS style_id, s.code AS style_code, s.name AS style_name, s.alias_name, s.tag_price,
       p.id AS tech_pack_id, p.stage, p.version
FROM tp_tech_pack p
JOIN sty_style s ON s.id = p.style_id
WHERE p.style_id IS NOT NULL AND p.status = 'EFFECTIVE'
  AND (p.stage = 'PROD'
       OR (p.stage = 'DEV' AND NOT EXISTS (SELECT 1 FROM tp_tech_pack x
                                           WHERE x.style_id = p.style_id AND x.stage = 'PROD' AND x.status = 'EFFECTIVE')))



    AND (upper(s.code) LIKE #{keywordCode} OR s.name ILIKE #{keywordContains}
         OR s.alias_name ILIKE #{keywordContains}
         OR upper(s.code) IN #{code})


    AND s.category_id IN #{id}

AND s.brand = #{q.brand}
AND s.year = #{q.year}
AND s.season = #{q.season}
AND p.stage = #{q.stage}
ORDER BY s.code DESC, s.id DESC

SELECT p.id,p.style_id,p.sample_id,
    CASE WHEN p.style_id IS NULL THEN s.company_id ELSE NULL END AS company_id,p.version_lock
FROM tp_tech_pack p LEFT JOIN dev_sample s ON s.id=p.sample_id WHERE p.id=#{id}
